use-this-data/","themes":["인물과 일상"],"taxonomy":{"periods":["20th-century"],"movements":[],"kind":"painting","subjects":["interior","figure","daily-life"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 기록","url":"https://open.smk.dk/artwork/image/KMS6658"}]},"image_width":1024,"image_height":838,"image_bytes":70627,"sha256":"8af3ba99f11271d3c9a8dadc0a08c1b0ba75cd8c9bc9333b0b7e663cb5a481c8","collected_at":"2026-10-13T07:21:22.618Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"smk-kms6692","museum":"SMK – National Gallery of Denmark","title":"Selvportræt","title_ko":"자화상","artist":"Hammershøi, Vilhelm","artist_ids":["vilhelm-hammershoi"],"artist_status":"identified","date":"1890","medium":"Olie på lærred","medium_ko":"캔버스에 유채","dimensions":"Netto: 52 x 39.5 cm; Brutto: 64.6 x 49.5 x 5.3 cm","dimensions_ko":"액자 제외: 52 × 39.5 cm; 액자 포함: 64.6 × 49.5 × 5.3 cm","description":"함메르쇼이가 1890년에 자신의 얼굴과 상반신을 그린 초상화입니다. 어두운 바탕 앞의 밝은 얼굴과 옆으로 향한 시선을 중심으로 구성해, 실내 풍경에서 자주 보이는 절제된 색을 인물에도 적용했습니다.","culture":"Denmark","accession":"KMS6692","source_url":"https://open.smk.dk/artwork/image/KMS6692","api_url":"https://api.smk.dk/api/v1/art?object_number=KMS6692","preview_url":"https://iip-thumb.smk.dk/iiif/jp2/2j62s789w_KMS6692.tif.reconstructed.tif.jp2/full/!1024,/0/default.jpg","image_url":"https://api.smk.dk/api/v1/download/W3siaW1nX3VybCI6Imh0dHBzOi8vaWlwLnNtay5kay9paWlmL2pwMi8yajYyczc4OXdfS01TNjY5Mi50aWYucmVjb25zdHJ1Y3RlZC50aWYuanAyL2Z1bGwvZnVsbC8wL25hdGl2ZS5qcGciLCJwdWJsaWNfZG9tYWluIjp0cnVlLCJvYmplY3RfbnVtYmVyIjoiS01TNjY5MiIsIm51bSI6IiJ9XQ==/KMS6692.jpg","license":"Public Domain (PDM 1.0)","license_evidence":{"public_domain":true,"rights":"https://creativecommons.org/publicdomain/mark/1.0/"},"policy_url":"https://hammershoi.smk.dk/use-this-data/","themes":["인물과 일상"],"taxonomy":{"periods":["modern"],"movements":[],"kind":"painting","subjects":["figure"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 기록","url":"https://open.smk.dk/artwork/image/KMS6692"}]},"image_width":1024,"image_height":1373,"image_bytes":155385,"sha256":"c55b8fe35012588b15e937e483b319468bb5810df20adbe7aca6926d31d62b90","collected_at":"2026-10-13T07:21:22.618Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"smk-kms3295","museum":"SMK – National Gallery of Denmark","title":"Frederikke Amalie Hammershøi, f. Rentzmann, kunstnerens moder","title_ko":"어머니 프레데리케 아말리에 함메르쇼이의 초상","artist":"Hammershøi, Vilhelm","artist_ids":["vilhelm-hammershoi"],"artist_status":"identified","date":"1894","medium":"Olie på lærred","medium_ko":"캔버스에 유채","dimensions":"Netto: 50 x 38 cm","dimensions_ko":"액자 제외: 50 × 38 cm","description":"흰 머리 장식과 검은 옷을 입은 함메르쇼이의 어머니를 그린 1894년 초상화입니다. 밝은 배경과 얼굴, 어두운 옷의 큰 면을 대비시키고, 시선과 손의 작은 변화에 집중한 가족 초상입니다.","culture":"Denmark","accession":"KMS3295","source_url":"https://open.smk.dk/artwork/image/KMS3295","api_url":"https://api.smk.dk/api/v1/art?object_number=KMS3295","preview_url":"https://iip-thumb.smk.dk/iiif/jp2/s1784q053_KMS3295.tif.reconstructed.tif.jp2/full/!1024,/0/default.jpg","image_url":"https://api.smk.dk/api/v1/download/W3siaW1nX3VybCI6Imh0dHBzOi8vaWlwLnNtay5kay9paWlmL2pwMi9zMTc4NHEwNTNfS01TMzI5NS50aWYucmVjb25zdHJ1Y3RlZC50aWYuanAyL2Z1bGwvZnVsbC8wL25hdGl2ZS5qcGciLCJwdWJsaWNfZG9tYWluIjp0cnVlLCJvYmplY3RfbnVtYmVyIjoiS01TMzI5NSIsIm51bSI6IiJ9XQ==/KMS3295.jpg","license":"Public Domain (PDM 1.0)","license_evidence":{"public_domain":true,"rights":"https://creativecommons.org/publicdomain/mark/1.0/"},"policy_url":"https://hammershoi.smk.dk/use-this-data/","themes":["인물과 일상"],"taxonomy":{"periods":["modern"],"movements":[],"kind":"painting","subjects":["figure"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 기록","url":"https://open.smk.dk/artwork/image/KMS3295"}]},"image_width":1024,"image_height":1401,"image_bytes":127302,"sha256":"9597aacb193cc79e50e670593b9943df0dba6dfaa157b0eba23143ae4413d92f","collected_at":"2026-10-13T07:21:22.618Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"nga-1236","museum":"National Gallery of Art","title":"Woman Holding a Balance","title_ko":"저울을 든 여인","artist":"Johannes Vermeer","artist_ids":["johannes-vermeer"],"artist_status":"identified","date":"c. 1664","medium":"oil on canvas","medium_ko":"캔버스에 유채","dimensions":"painted surface: 39.7 x 35.5 cm (15 5/8 x 14 in.); stretcher size: 42.5 x 38 cm (16 3/4 x 14 15/16 in.); framed: 62.9 x 58.4 x 7.6 cm (24 3/4 x 23 x 3 in.)","dimensions_ko":"그림 면: 39.7 × 35.5 cm; 캔버스 틀: 42.5 × 38 cm; 액자 포함: 62.9 × 58.4 × 7.6 cm","description":"창에서 들어오는 빛 아래 여인이 작은 저울을 들고 서 있습니다. 탁자의 보석과 뒤쪽의 최후의 심판 그림이 함께 놓여 있어, 조용한 일상 장면 안에서 균형과 판단의 의미를 생각하게 합니다.","culture":"Dutch","accession":"1942.9.97","source_url":"https://www.nga.gov/artworks/1236-woman-holding-balance","preview_url":"https://api.nga.gov/iiif/c948cf32-e6c7-41a0-a053-0ad0562960c4/full/1200,/0/default.jpg","image_url":"https://api.nga.gov/iiif/c948cf32-e6c7-41a0-a053-0ad0562960c4/full/full/0/default.jpg","license":"CC0","license_evidence":{"object_media_public_domain":true,"object_notice":"This object’s media is free and in the public domain."},"policy_url":"https://www.nga.gov/terms-and-notices","themes":["신화와 상상"],"taxonomy":{"periods":["early-modern"],"movements":["baroque"],"kind":"painting","subjects":["interior","figure","daily-life","religion-myth"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 기록","url":"https://www.nga.gov/artworks/1236-woman-holding-balance"},{"label":"미술관 · 사조·양식 맥락","url":"https://www.metmuseum.org/zh/essays/portraiture-in-renaissance-and-baroque-europe"}]},"image_width":1200,"image_height":1358,"image_bytes":322273,"sha256":"dac0f393657e847a6e5f17459a6ebefba095b46a7b74dcdf78e110c4a5a1d574","collected_at":"2026-10-13T07:21:22.618Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"nga-60","museum":"National Gallery of Art","title":"Girl with the Red Hat","title_ko":"붉은 모자를 쓴 소녀","artist":"Johannes Vermeer","artist_ids":["johannes-vermeer"],"artist_status":"identified","date":"c. 1669","medium":"oil on panel","medium_ko":"목판에 유채","dimensions":"painted surface: 22.8 x 18 cm (9 x 7 1/16 in.); support: 23.2 x 18.1 cm (9 1/8 x 7 1/8 in.); framed: 40.3 x 35.6 x 4.4 cm (15 7/8 x 14 x 1 3/4 in.)","dimensions_ko":"그림 면: 22.8 × 18 cm; 지지체: 23.2 × 18.1 cm; 액자 포함: 40.3 × 35.6 × 4.4 cm","description":"붉은 모자와 푸른 옷을 입은 소녀가 몸을 돌려 관람자를 바라봅니다. 베르메르가 캔버스 대신 패널에 그린 작은 작품으로, 큰 색의 대비와 진주·얼굴에 놓인 밝은 반사광이 시선을 모읍니다.","culture":"Dutch","accession":"1937.1.53","source_url":"https://www.nga.gov/artworks/60-girl-red-hat","preview_url":"https://api.nga.gov/iiif/b705a403-3496-42e8-abf5-a37e34c32198/full/1200,/0/default.jpg","image_url":"https://api.nga.gov/iiif/b705a403-3496-42e8-abf5-a37e34c32198/full/full/0/default.jpg","license":"CC0","license_evidence":{"object_media_public_domain":true,"object_notice":"This object’s media is free and in the public domain."},"policy_url":"https://www.nga.gov/terms-and-notices","themes":["인물과 일상"],"taxonomy":{"periods":["early-modern"],"movements":["baroque"],"kind":"painting","subjects":["interior","figure"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 기록","url":"https://www.nga.gov/artworks/60-girl-red-hat"},{"label":"미술관 · 사조·양식 맥락","url":"https://www.metmuseum.org/zh/essays/portraiture-in-renaissance-and-baroque-europe"}]},"image_width":1200,"image_height":1517,"image_bytes":378526,"sha256":"bbccb37bd5dfd02c42d69770c9bbf19f0c10a4ebd3b8962ece3a312a07748f0a","collected_at":"2026-10-13T07:21:22.621Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"nga-74796","museum":"National Gallery of Art","title":"The Japanese Footbridge","title_ko":"일본식 다리","artist":"Claude Monet","artist_ids":["claude-monet"],"artist_status":"identified","date":"1899","medium":"oil on canvas","medium_ko":"캔버스에 유채","dimensions":"overall: 81.3 x 101.6 cm (32 x 40 in.); framed: 101 x 120.7 x 7.6 cm (39 3/4 x 47 1/2 x 3 in.)","dimensions_ko":"전체: 81.3 × 101.6 cm; 액자 포함: 101 × 120.7 × 7.6 cm","description":"지베르니의 수련 연못 위에 놓인 청록색 다리를 그린 1899년 풍경입니다. 수련과 풀, 나무의 초록이 물의 반영과 이어지며, 다리의 아치와 수면의 작은 붓질이 서로 다른 리듬을 만듭니다.","culture":"French","accession":"1992.9.1","source_url":"https://www.nga.gov/artworks/74796-japanese-footbridge","preview_url":"https://api.nga.gov/iiif/0b9cefb5-1ee4-401a-8154-8d4039191a28/full/1200,/0/default.jpg","image_url":"https://api.nga.gov/iiif/0b9cefb5-1ee4-401a-8154-8d4039191a28/full/full/0/default.jpg","license":"CC0","license_evidence":{"object_media_public_domain":true,"object_notice":"This object’s media is free and in the public domain."},"policy_url":"https://www.nga.gov/terms-and-notices","themes":["풍경과 빛"],"taxonomy":{"periods":["modern"],"movements":["impressionism"],"kind":"painting","subjects":["landscape","nature"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 기록","url":"https://www.nga.gov/artworks/74796-japanese-footbridge"},{"label":"미술관 · 사조·양식 맥락","url":"https://www.metmuseum.org/essays/impressionism-art-and-modernity"}]},"image_width":1200,"image_height":967,"image_bytes":465528,"sha256":"4c182e2181f18857ef8e581b03d1b6f84a9529d1923765dbc041355e6cc342f3","collected_at":"2026-10-13T07:21:22.620Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"nga-61374","museum":"National Gallery of Art","title":"The Bridge at Argenteuil","title_ko":"아르장퇴유의 다리","artist":"Claude Monet","artist_ids":["claude-monet"],"artist_status":"identified","date":"1874","medium":"oil on canvas","medium_ko":"캔버스에 유채","dimensions":"overall: 60 x 79.7 cm (23 5/8 x 31 3/8 in.); framed: 78.1 x 97.8 x 4.7 cm (30 3/4 x 38 1/2 x 1 7/8 in.)","dimensions_ko":"전체: 60 × 79.7 cm; 액자 포함: 78.1 × 97.8 × 4.7 cm","description":"아르장퇴유의 센강 위에 다리와 배들이 놓인 햇빛 밝은 풍경입니다. 짧고 분리된 붓질은 가까이에서 색의 흔적으로 보이고, 떨어져 보면 물결과 하늘·나무를 이루어 빛의 변화를 표현합니다.","culture":"French","accession":"1983.1.24","source_url":"https://www.nga.gov/artworks/61374-bridge-argenteuil","preview_url":"https://api.nga.gov/iiif/7372b15a-3830-43bf-8c41-4836619312b7/full/1200,/0/default.jpg","image_url":"https://api.nga.gov/iiif/7372b15a-3830-43bf-8c41-4836619312b7/full/full/0/default.jpg","license":"CC0","license_evidence":{"object_media_public_domain":true,"object_notice":"This object’s media is free and in the public domain."},"policy_url":"https://www.nga.gov/terms-and-notices","themes":["인물과 일상"],"taxonomy":{"periods":["modern"],"movements":["impressionism"],"kind":"painting","subjects":["landscape","figure","daily-life"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 기록","url":"https://www.nga.gov/artworks/61374-bridge-argenteuil"},{"label":"미술관 · 사조·양식 맥락","url":"https://www.metmuseum.org/essays/impressionism-art-and-modernity"}]},"image_width":1200,"image_height":900,"image_bytes":374871,"sha256":"1b96df48f53fa1f934ec523c4887f3fa9a81fd20cd64a70b63ce1f687cbcaabf","collected_at":"2026-10-13T07:21:22.620Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"nga-5938","museum":"National Gallery of Art","title":"The Letter","title_ko":"편지","artist":"Mary Cassatt","artist_ids":["mary-cassatt"],"artist_status":"identified","date":"1890-1891","medium":"color drypoint, softground etching, and aquatint","medium_ko":"다색 드라이포인트·소프트그라운드 에칭·애쿼틴트","dimensions":"plate: 36.6 x 22.6 cm (14 7/16 x 8 7/8 in.); sheet: 47.7 x 30.8 cm (18 3/4 x 12 1/8 in.)","dimensions_ko":"판: 36.6 × 22.6 cm; 종이 전체: 47.7 × 30.8 cm","description":"책상 앞에 앉은 여성이 편지 봉투를 입에 대어 봉하는 장면입니다. 푸른 옷과 꽃무늬 벽지, 책상 위의 종이를 평평한 색과 섬세한 선으로 이어, 짧은 일상 동작을 화면의 중심에 놓았습니다.","culture":"American","accession":"1943.3.2763","source_url":"https://www.nga.gov/artworks/5938-letter","preview_url":"https://api.nga.gov/iiif/933ca1ed-8152-4a59-90ad-841dd481d350/full/1200,/0/default.jpg","image_url":"https://api.nga.gov/iiif/933ca1ed-8152-4a59-90ad-841dd481d350/full/full/0/default.jpg","license":"CC0","license_evidence":{"object_media_public_domain":true,"object_notice":"This object’s media is free and in the public domain."},"policy_url":"https://www.nga.gov/terms-and-notices","themes":["인물과 일상"],"taxonomy":{"periods":["modern"],"movements":["impressionism"],"kind":"print","subjects":["interior","figure","daily-life"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 기록","url":"https://www.nga.gov/artworks/5938-letter"},{"label":"미술관 · 사조·양식 맥락","url":"https://www.metmuseum.org/essays/impressionism-art-and-modernity"}]},"image_width":1200,"image_height":1849,"image_bytes":688464,"sha256":"2768f00764ee3e4ce700f305b2e5695b7cd9e55a257eaff1acfc13e4c35d3b46","collected_at":"2026-10-13T07:21:22.621Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"nga-46482","museum":"National Gallery of Art","title":"Portrait of a Lady","title_ko":"여성의 초상","artist":"Mary Cassatt","artist_ids":["mary-cassatt"],"artist_status":"identified","date":"c. 1887","medium":"oil on canvas","medium_ko":"캔버스에 유채","dimensions":"overall: 72.9 x 60.3 cm (28 11/16 x 23 3/4 in.); framed: 100.3 x 84.1 cm (39 1/2 x 33 1/8 in.)","dimensions_ko":"전체: 72.9 × 60.3 cm; 액자 포함: 100.3 × 84.1 cm","description":"꽃으로 장식한 검은 모자를 쓴 여성이 의자에 기대 앉은 초상입니다. 밝은 배경과 어두운 옷 사이로 얼굴과 장갑 낀 손을 드러냈으며, 모델의 구체적인 이름은 확인되지 않아 원제의 범위를 유지합니다.","culture":"American","accession":"1963.10.7","source_url":"https://www.nga.gov/artworks/46482-portrait-lady","preview_url":"https://api.nga.gov/iiif/2af9c50c-0aab-41ef-999a-1ab213713b39/full/1200,/0/default.jpg","image_url":"https://api.nga.gov/iiif/2af9c50c-0aab-41ef-999a-1ab213713b39/full/full/0/default.jpg","license":"CC0","license_evidence":{"object_media_public_domain":true,"object_notice":"This object’s media is free and in the public domain."},"policy_url":"https://www.nga.gov/terms-and-notices","themes":["인물과 일상"],"taxonomy":{"periods":["modern"],"movements":["impressionism"],"kind":"painting","subjects":["figure"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 기록","url":"https://www.nga.gov/artworks/46482-portrait-lady"},{"label":"미술관 · 사조·양식 맥락","url":"https://www.metmuseum.org/essays/impressionism-art-and-modernity"}]},"image_width":1200,"image_height":1465,"image_bytes":394030,"sha256":"b5411f1c7e106cf81c40caf079ed45611a7735663a8f4f2cd7f8174300d190d1","collected_at":"2026-10-13T07:21:22.623Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"nga-129319","museum":"National Gallery of Art","title":"Cairo","title_ko":"카이로","artist":"John Singer Sargent","artist_ids":["john-singer-sargent"],"artist_status":"identified","date":"c. 1891","medium":"watercolor over graphite on wove paper","medium_ko":"직조지에 흑연 밑그림·수채","dimensions":"sheet: 25.4 × 35.5 cm (10 × 14 in.)","dimensions_ko":"종이 전체: 25.4 × 35.5 cm","description":"가까운 돌벽과 멀리 보이는 모스크의 첨탑을 함께 그린 카이로 풍경입니다. 회색·크림색·분홍빛 돌과 푸른 그림자를 유연한 수채 붓질로 이어, 사전트의 여행지 관찰을 보여 줍니다.","culture":"American","accession":"2010.93.7","source_url":"https://www.nga.gov/artworks/129319-cairo","preview_url":"https://api.nga.gov/iiif/22c24af2-20de-4f78-88c2-eb082c0c58c3/full/1200,/0/default.jpg","image_url":"https://api.nga.gov/iiif/22c24af2-20de-4f78-88c2-eb082c0c58c3/full/full/0/default.jpg","license":"CC0","license_evidence":{"object_media_public_domain":true,"object_notice":"This object’s media is free and in the public domain."},"policy_url":"https://www.nga.gov/terms-and-notices","themes":["풍경과 빛"],"taxonomy":{"periods":["modern"],"movements":[],"kind":"drawing","subjects":["landscape"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 기록","url":"https://www.nga.gov/artworks/129319-cairo"}]},"image_width":1200,"image_height":852,"image_bytes":300085,"sha256":"1e73ef682bb2864586afe1e92b8e3a76e07407fb8c7ba3b9bb3688b6185a40cb","collected_at":"2026-10-13T07:21:22.623Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"nga-35080","museum":"National Gallery of Art","title":"Nonchaloir (Repose)","title_ko":"느긋함 — 휴식","artist":"John Singer Sargent","artist_ids":["john-singer-sargent"],"artist_status":"identified","date":"1911","medium":"oil on canvas","medium_ko":"캔버스에 유채","dimensions":"overall: 63.8 × 76.2 cm (25 1/8 × 30 in.); framed: 82.87 × 96.2 × 6.99 cm (32 5/8 × 37 7/8 × 2 3/4 in.)","dimensions_ko":"전체: 63.8 × 76.2 cm; 액자 포함: 82.87 × 96.2 × 6.99 cm","description":"사전트의 조카 로즈마리 오먼드가 소파에 느긋하게 기대 있는 모습을 그렸습니다. 은빛 치마와 흰 천의 긴 주름, 금빛 액자와 실내의 밝은 색이 겹쳐져, 격식 있는 초상보다 편안한 자세에 집중합니다.","culture":"American","accession":"1948.16.1","source_url":"https://www.nga.gov/artworks/35080-nonchaloir-repose","preview_url":"https://api.nga.gov/iiif/718e014f-fb5f-4702-a95a-db496abefeb7/full/1200,/0/default.jpg","image_url":"https://api.nga.gov/iiif/718e014f-fb5f-4702-a95a-db496abefeb7/full/full/0/default.jpg","license":"CC0","license_evidence":{"object_media_public_domain":true,"object_notice":"This object’s media is free and in the public domain."},"policy_url":"https://www.nga.gov/terms-and-notices","themes":["인물과 일상"],"taxonomy":{"periods":["20th-century"],"movements":[],"kind":"painting","subjects":["interior","figure","daily-life"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 기록","url":"https://www.nga.gov/artworks/35080-nonchaloir-repose"}]},"image_width":1200,"image_height":1004,"image_bytes":358970,"sha256":"496e8fee4b06c2241e8c17d165bedcdd295e0088000f14cd212bb1908cb66c6b","collected_at":"2026-10-13T07:21:22.623Z","title_ko_status":"working_translation","themes_status":"editorial_classification"},{"id":"nga-166436","museum":"National Gallery of Art","title":"Niagara","title_ko":"나이아가라","artist":"Frederic Edwin Church","artist_ids":["frederic-edwin-church"],"artist_status":"identified","date":"1857","medium":"oil on canvas","medium_ko":"캔버스에 유채","dimensions":"overall: 101.6 × 229.9 cm (40 × 90 1/2 in.); framed: 164.5 × 286.4 × 17.8 cm (64 3/4 × 112 3/4 × 7 in.)","dimensions_ko":"전체: 101.6 × 229.9 cm; 액자 포함: 164.5 × 286.4 × 17.8 cm","description":"나이아가라의 호스슈 폭포를 물 바로 위에서 바라보는 듯한 시점으로 그렸습니다. 거품과 물안개, 멀리 보이는 무지개를 가로로 긴 화면에 펼쳐, 떨어지는 물의 힘과 넓은 풍경을 함께 전달합니다.","culture":"American","accession":"2014.79.10","source_url":"https://www.nga.gov/artworks/166436-niagara","preview_url":"https://api.nga.gov/iiif/4d6a4fa1-db74-4586-a753-9951bc5945a3/full/1200,/0/default.jpg","image_url":"https://api.nga.gov/iiif/4d6a4fa1-db74-4586-a753-9951bc5945a3/full/full/0/default.jpg","license":"CC0","license_evidence":{"object_media_public_domain":true,"object_notice":"This object’s media is free and in the public domain."},"policy_url":"https://www.nga.gov/terms-and-notices","themes":["풍경과 빛"],"taxonomy":{"periods":["modern"],"movements":[],"kind":"painting","subjects":["landscape"],"sources":[{"label":"소장처 · 제작 시기·재료·작품 기록","url":"https://www.nga.gov/artworks/166436-niagara"}]},"image_width":1200,"image_height":557,"image_bytes":158684,"sha256":"200eeba1139cf55140ed98014a957c9674ed150afd436d012a20f48c08f1f3f1","collected_at":"2026-10-13T07:21:22.623Z","title_ko_status":"working_translation","themes_status":"editorial_classification"}]$works$::jsonb;
 supplemental_sources jsonb := $sources$[{"id":"johannes-vermeer","source_ids":["nga:1951"]},{"id":"claude-monet","source_ids":["nga:1726"]},{"id":"john-singer-sargent","source_ids":["nga:1858"]},{"id":"frederic-edwin-church","source_ids":["nga:1138"]}]$sources$::jsonb;
BEGIN
 LOCK TABLE public.artists, public.artworks, public.artwork_artists IN SHARE ROW EXCLUSIVE MODE;
 IF EXISTS (SELECT 1 FROM jsonb_array_elements(works) item CROSS JOIN LATERAL jsonb_array_elements_text(item->'artist_ids') person WHERE NOT EXISTS (SELECT 1 FROM public.artists a WHERE a.id=person)) THEN
  RAISE EXCEPTION 'Missing existing artist: no catalog content was changed';
 END IF;
 IF EXISTS (SELECT 1 FROM jsonb_array_elements(works) item JOIN public.artworks w ON w.id=item->>'id' WHERE w.data IS DISTINCT FROM item - 'artist_ids') THEN
  RAISE EXCEPTION 'Artwork ID conflict: no existing content was changed';
 END IF;
 IF EXISTS (SELECT 1 FROM jsonb_array_elements(works) item JOIN public.artwork_artists link ON link.artwork_id=item->>'id' WHERE NOT (item->'artist_ids' ? link.artist_id)) THEN
  RAISE EXCEPTION 'Conflicting artist attribution: no existing content was changed';
 END IF;
 INSERT INTO public.artworks(id,data)
 SELECT item->>'id',item - 'artist_ids' FROM jsonb_array_elements(works) item ON CONFLICT (id) DO NOTHING;
 INSERT INTO public.artwork_artists(artwork_id,artist_id)
 SELECT item->>'id',person FROM jsonb_array_elements(works) item CROSS JOIN LATERAL jsonb_array_elements_text(item->'artist_ids') person ON CONFLICT DO NOTHING;
 UPDATE public.artists a
 SET source_ids=ARRAY(SELECT DISTINCT source_id FROM unnest(a.source_ids || ARRAY(SELECT jsonb_array_elements_text(item->'source_ids'))) source_id ORDER BY source_id)
 FROM jsonb_array_elements(supplemental_sources) item
 WHERE a.id=item->>'id' AND NOT a.source_ids @> ARRAY(SELECT jsonb_array_elements_text(item->'source_ids'));
END;
$catalog_addition$;
